{"tool": "final", "content": "function splitStringWithDelimiters (string, delimiters) { 
  let result = []; 
  let s = string; 
  while (s.length > 0) { 
    let char = s[0]; 
    if (delimiters.includes(char)) { 
      s = s.substr(1); 
    } else { 
      let index = 0; 
      for (const delimiter of delimiters) { 
        if (s.indexOf(delimiter) > 0 && s.indexOf(delimiter) < index) { 
          index = s.indexOf(delimiter); 
        } 
      } 
      if (index === 0) { 
        index = s.length; 
      } 
      result.push(s.substr(0, index)); 
      s = s.substr(index); 
    } 
  } 
  return result; 
}"}

