{"tool": "final", "content": "def longestSubsequence(x, y): 
    m = len(x) 
    n = len(y) 

    L = [[None]*(n+1) for i in range(m+1)] 

    for i in range(m + 1): 
        for j in range(n + 1): 
            if i == 0 or j == 0 : 
                L[i][j] = 0
            elif x[i-1] == y[j-1]: 
                L[i][j] = L[i-1][j-1]+1
            else: 
                L[i][j] = max(L[i-1][j] , L[i][j-1]) 

    index = L[m][n] 

    lcs = [""] * (index+1) 
    lcs[index] = "\0" 

    i = m 
    j = n 
    while i > 0 and j > 0: 

        if x[i-1] == y[j-1]: 
            lcs[index-1] = x[i-1] 
            i-=1
            j-=1
            index-=1

        elif L[i-1][j] > L[i][j-1]: 
            i-=1
        else: 
            j-=1

    print("Longest common subsequence of " + x + " and " + y + " is \"" + "".join(lcs) + "\"")"}

{"tool": "final", "content": "function toRoman(num) {
    // store roman equivalents of numbers
    var romanNumerals = {
        1: 'I',
        4: 'IV',
        5: 'V',
        9: 'IX',
        10: 'X',
        40: 'XL',
        50: 'L'
    };

    // array to store roman numeral
    var roman = [];

    // loop to check for roman equivalents
    for (let i = Object.keys(romanNumerals).length; i >= 0; i--) {
        let div = Math.floor(num / Object.keys(romanNumerals)[i]);
        let rem = num % Object.keys(romanNumerals)[i];

        if (div > 0) {
            roman.push(romanNumerals[Object.keys(romanNumerals)[i]].repeat(div));
            num = rem;
        }
    }

    // return the new created string
    return roman.join("");
}"}

{"tool": "final", "content": "int compareToFindSmallest(int[] numbers, int targetIndex) {

    int smallestIndex = 0;
    for (int i = 1; i < numbers.length; i++) 
    {
        if (numbers[i] < numbers[smallestIndex]) {
            smallestIndex = i;
        }
    }

    int tempIndex = smallestIndex;
    int resultIndex = -1;
    int count = 0;
    while (resultIndex == -1) {
        count++;
        if (smallestIndex == tempIndex) {
            if (count == targetIndex) {
                resultIndex = tempIndex;
            }
            tempIndex++;
        } else {
            if (numbers[tempIndex] == numbers[smallestIndex]) {
                if (count == targetIndex) {
                    resultIndex = tempIndex;
                }
                tempIndex++;
            } else {
                smallestIndex = tempIndex;
            }
        }

        if (tempIndex >= numbers.length) {
            tempIndex = smallestIndex + 1;
        }
    }

    return resultIndex;
}

