public static void findPair(int[] arr) { 
    int pairIndex = -1; 

    // Loop through the array 
    for (int i = 0; i < arr.length; i++) { 
        int current = arr[i]; 

        // Check if it's a matching pair 
        for (int j = i + 1; j < arr.length; j++) { 
            if (current == arr[j]) { 
                pairIndex = j; 
                break; 
            } 
        } 
    } 

